// Vera | Mindmaker OS | Behavioural Auditor (v3 — executions-based)
// Reads execution truth from n8n /executions instead of workflow_runs proxy table.
// Auto-derives cadence per workflow from its trigger nodes.
// Sandbox-safe: uses this.helpers.httpRequest. No fetch. No $env.

const __helpers = this.helpers;

async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const hasBody = opts.body !== undefined && opts.body !== null;

  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (hasBody) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }

  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const msg = (body && body.message) ? body.message : (err.message || String(err));
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + msg);
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }

  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ' on ' + method + ' ' + url);
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return { statusCode: status, headers: res.headers || {}, body };
}

// ---------- config ----------
const startedAt = Date.now();

let auditType = 'daily';
try {
  const items = $input.all();
  if (items && items[0] && items[0].json && items[0].json.audit_type) {
    auditType = items[0].json.audit_type;
  }
} catch (e) {}
const dayOfWeek = new Date().getUTCDay();
const utcHour = new Date().getUTCHours();
if (auditType === 'daily' && dayOfWeek === 5 && utcHour >= 10 && utcHour <= 12) {
  auditType = 'weekly';
}

const N8N_BASE = 'https://krishraja10101.app.n8n.cloud/api/v1';
const N8N_KEY  = '{{N8N_API_JWT}}';
const SB_URL  = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SB_KEY  = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const TG_BOT  = '{{TELEGRAM_BOT_TOKEN}}';
const TG_CHAT = '6773796504';

const MAX_WORKFLOWS = 50;
const EXECUTIONS_PER_WF = 20;
const ERROR_RATE_THRESHOLD = 0.5;   // 50% of last 20 runs errored -> medium finding
const CONSECUTIVE_ERRORS_RED = 3;   // last 3 consecutive errors -> high finding
const WEBHOOK_SILENCE_HOURS = 24 * 7;
const MANUAL_TRIGGER_GRACE_HOURS = 24 * 14;

const n8nHeaders = { 'X-N8N-API-KEY': N8N_KEY };
const sbHeaders  = { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };
const sbWriteHeaders = Object.assign({}, sbHeaders, { Prefer: 'return=representation' });

// ---------- n8n helpers ----------
async function n8nGet(path) {
  try {
    const r = await __httpRequest({ method: 'GET', url: N8N_BASE + path, headers: n8nHeaders });
    return r.body;
  } catch (e) {
    throw new Error('n8nGet failed on ' + path + ': ' + (e.message || e));
  }
}

async function sbPost(table, body) {
  try {
    const r = await __httpRequest({ method: 'POST', url: SB_URL + '/rest/v1/' + table, headers: sbWriteHeaders, body });
    return r.body;
  } catch (e) {
    return { error: String(e.message || e), httpCode: e.httpCode || 0 };
  }
}

// ---------- cron parsing ----------
// Derive min interval in hours from a standard 5-field cron expression
// Field order: minute hour dom month dow
function cronToHours(expr) {
  if (!expr || typeof expr !== 'string') return null;
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 5) return null;
  const [mn, hr, dom, mo, dow] = parts;

  // Check minute-level frequency
  if (mn.includes(',')) return 1;                          // multiple minute values within an hour
  if (mn.startsWith('*/')) {
    const step = Number(mn.slice(2));
    if (step && step > 0) return step / 60;
  }
  if (mn === '*') return 1/60;                             // every minute (pathological)

  // Hour-level
  if (hr === '*') return 1;                                // every hour
  if (hr.startsWith('*/')) {
    const step = Number(hr.slice(2));
    if (step && step > 0) return step;
  }
  if (hr.includes(',')) {
    const hours = hr.split(',').map(Number).filter(n => !Number.isNaN(n));
    if (hours.length >= 2) {
      // Approximate: 24/count of specified hours
      return Math.ceil(24 / hours.length);
    }
  }

  // Day-of-month weekly/etc
  if (dom === '*' && dow === '*') return 24;               // daily
  if (dow !== '*') {
    // Weekly schedule. Count days of week specified.
    let days = 1;
    if (dow.includes(',')) days = dow.split(',').length;
    else if (dow.includes('-')) {
      const [a, b] = dow.split('-').map(Number);
      if (!Number.isNaN(a) && !Number.isNaN(b)) days = (b - a + 1);
    }
    return Math.ceil((24 * 7) / Math.max(days, 1));
  }

  if (dom !== '*') return 24 * 30;                         // monthly-ish fallback

  return 24;  // safe daily default
}

function classifyWorkflow(wf) {
  const nodes = wf.nodes || [];
  let trigger_type = 'manual_only';
  let minIntervalHours = null;
  for (const n of nodes) {
    const t = n.type || '';
    const p = n.parameters || {};
    if (t === 'n8n-nodes-base.scheduleTrigger') {
      trigger_type = 'cron';
      const rule = p.rule || {};
      for (const ivl of (rule.interval || [])) {
        let h = null;
        if (ivl.field === 'cronExpression') h = cronToHours(ivl.expression);
        else if (ivl.field === 'minutes' && ivl.minutesInterval) h = ivl.minutesInterval / 60;
        else if (ivl.field === 'hours' && ivl.hoursInterval)   h = ivl.hoursInterval;
        else if (ivl.field === 'days' && ivl.daysInterval)     h = ivl.daysInterval * 24;
        else if (ivl.field === 'weeks')                         h = 24 * 7;
        if (h !== null && (minIntervalHours === null || h < minIntervalHours)) minIntervalHours = h;
      }
    } else if (t === 'n8n-nodes-base.webhook' && trigger_type !== 'cron') {
      trigger_type = 'webhook';
    } else if ((t === 'n8n-nodes-base.gmailTrigger' || t === 'n8n-nodes-base.emailReadImap') && trigger_type !== 'cron') {
      trigger_type = 'event';
    }
  }
  // Compute max_silence_hours per trigger type
  let max_silence_hours;
  if (trigger_type === 'cron') {
    // 1.5x interval, min 2h floor so a daily job has ~36h silence allowance
    max_silence_hours = Math.max(2, Math.ceil((minIntervalHours || 24) * 1.5));
  } else if (trigger_type === 'webhook') {
    max_silence_hours = WEBHOOK_SILENCE_HOURS;
  } else if (trigger_type === 'event') {
    max_silence_hours = WEBHOOK_SILENCE_HOURS;
  } else {
    max_silence_hours = MANUAL_TRIGGER_GRACE_HOURS;
  }
  return { trigger_type, min_interval_hours: minIntervalHours, max_silence_hours };
}

// Extract agent prefix from workflow name e.g. "Leo | Mindmaker OS | ..." -> "Leo"
function prefixOf(name) {
  if (!name) return 'Unknown';
  const first = String(name).split('|')[0].trim();
  return first || 'Unknown';
}

// ---------- main audit ----------
const findings = [];
const auditedIds = [];
let cleanFlag = true;
const stats = { cron: 0, webhook: 0, event: 0, manual_only: 0, skipped: 0, errored_meta: 0 };

// Enumerate active workflows
const wfList = await n8nGet('/workflows?active=true&limit=100');
const workflows = (wfList && wfList.data) || [];
if (workflows.length === 0) {
  findings.push({ band: 'meta', severity: 'high', subject: 'vera', reason: 'no active workflows returned by /workflows?active=true' });
  cleanFlag = false;
}

const toAudit = workflows.slice(0, MAX_WORKFLOWS);
const now = Date.now();

for (const summary of toAudit) {
  const wfId = summary.id;
  const wfName = summary.name || wfId;
  auditedIds.push(wfId);

  // Full workflow fetch for trigger classification
  let wf;
  try {
    wf = await n8nGet('/workflows/' + wfId);
  } catch (e) {
    findings.push({ band: 'meta', severity: 'medium', subject: wfName, reason: 'fetch workflow failed: ' + String(e.message || e).substring(0, 140) });
    stats.errored_meta++;
    continue;
  }

  const classification = classifyWorkflow(wf);
  stats[classification.trigger_type] = (stats[classification.trigger_type] || 0) + 1;

  if (classification.trigger_type === 'manual_only') {
    stats.skipped++;
    continue;  // don't audit manual-only workflows
  }

  // Pull last N executions
  let execs;
  try {
    const r = await n8nGet('/executions?workflowId=' + encodeURIComponent(wfId) + '&limit=' + EXECUTIONS_PER_WF);
    execs = (r && r.data) || [];
  } catch (e) {
    findings.push({ band: 'meta', severity: 'medium', subject: wfName, reason: 'fetch executions failed: ' + String(e.message || e).substring(0, 140) });
    stats.errored_meta++;
    continue;
  }

  // Check 1: cadence silence
  if (execs.length === 0) {
    // Zero-history for webhook/event triggers is not actionable — it may simply never have been called.
    // Only flag as high for cron (which should have fired by now).
    if (classification.trigger_type === 'cron') {
      const intervalLabel = classification.min_interval_hours != null ? ('~' + classification.min_interval_hours + 'h') : 'unknown interval';
      findings.push({
        band: 'cadence', severity: 'high', subject: wfName,
        reason: 'no executions in history (cron, expected every ' + intervalLabel + ')',
        trigger_type: classification.trigger_type,
      });
      cleanFlag = false;
    }
    // Webhook/event with zero history: silently skip — not a finding.
    continue;
  }

  const latest = execs[0];
  const latestStartedAt = latest.startedAt ? new Date(latest.startedAt).getTime() : null;
  const hoursSince = latestStartedAt ? ((now - latestStartedAt) / 3600000) : 999;

  if (hoursSince > classification.max_silence_hours) {
    findings.push({
      band: 'cadence',
      severity: classification.trigger_type === 'cron' ? 'high' : 'medium',
      subject: wfName,
      reason: 'last execution ' + hoursSince.toFixed(1) + 'h ago (allowed ' + classification.max_silence_hours + 'h for ' + classification.trigger_type + ')',
      trigger_type: classification.trigger_type,
      hours_since: Math.round(hoursSince),
    });
    cleanFlag = false;
  }

  // Check 2: consecutive errors at the top of history
  const consecutiveErrors = [];
  for (const e of execs) {
    if (e.status === 'error') consecutiveErrors.push(e);
    else break;
  }

  // Check 3: error rate over last N (compute first, decide what to emit)
  let highRate = false;
  let errorCount = 0;
  if (execs.length >= 5) {
    errorCount = execs.filter(e => e.status === 'error').length;
    const rate = errorCount / execs.length;
    highRate = rate >= ERROR_RATE_THRESHOLD;
  }

  // Emit errors finding — avoid duplicates.
  // If we'd emit both "last 3+ errored" and "rate high", keep only the high one.
  // If only one error in last run AND rate is high, keep only the rate finding.
  if (consecutiveErrors.length >= CONSECUTIVE_ERRORS_RED) {
    findings.push({
      band: 'errors', severity: 'high', subject: wfName,
      reason: 'last ' + consecutiveErrors.length + ' executions all errored (most recent: ' + (consecutiveErrors[0].startedAt || '') + ')',
    });
    cleanFlag = false;
  } else if (highRate) {
    findings.push({
      band: 'errors', severity: 'medium', subject: wfName,
      reason: errorCount + '/' + execs.length + ' recent executions errored (' + Math.round((errorCount / execs.length) * 100) + '%)',
    });
    cleanFlag = false;
  } else if (consecutiveErrors.length >= 1 && latest.status === 'error') {
    findings.push({
      band: 'errors', severity: 'medium', subject: wfName,
      reason: 'most recent execution errored (' + consecutiveErrors.length + ' consecutive)',
    });
    cleanFlag = false;
  }
}

// ---------- autonomy demotion check (weekly only) ----------
let autonomyFindings = [];
if (auditType === 'weekly') {
  const DEMOTION_THRESHOLD = 0.15; // >15 percentage-point week-over-week jump in rejection rate
  const REJECTABLE_STATUSES = ['queued', 'sent', 'rejected']; // denominator: all attempted sends
  const nowMs = Date.now();
  const weekMs = 7 * 24 * 3600 * 1000;
  const thisWeekStart = new Date(nowMs - weekMs).toISOString();
  const lastWeekStart = new Date(nowMs - 2 * weekMs).toISOString();
  const lastWeekEnd = thisWeekStart;

  async function fetchSendsWithVenture(fromIso, toIso) {
    // acquisition_sends has no venture column directly -- join via lead_id -> leads.primary_venture.
    // PostgREST embed: select lead:leads(primary_venture)
    const path = '/rest/v1/acquisition_sends?select=status,queued_at,lead:leads(primary_venture)'
      + '&queued_at=gte.' + encodeURIComponent(fromIso)
      + (toIso ? ('&queued_at=lt.' + encodeURIComponent(toIso)) : '');
    const r = await __httpRequest({ method: 'GET', url: SB_URL + path, headers: sbHeaders });
    return Array.isArray(r.body) ? r.body : [];
  }

  function rejectionRateByVenture(rows) {
    const byVenture = {};
    for (const row of rows) {
      const venture = row.lead && row.lead.primary_venture;
      if (!venture) continue;
      if (!REJECTABLE_STATUSES.includes(row.status)) continue;
      if (!byVenture[venture]) byVenture[venture] = { total: 0, rejected: 0 };
      byVenture[venture].total++;
      if (row.status === 'rejected') byVenture[venture].rejected++;
    }
    const rates = {};
    for (const [venture, c] of Object.entries(byVenture)) {
      rates[venture] = c.total > 0 ? (c.rejected / c.total) : null;
    }
    return rates;
  }

  try {
    const [thisWeekRows, lastWeekRows] = await Promise.all([
      fetchSendsWithVenture(thisWeekStart, null),
      fetchSendsWithVenture(lastWeekStart, lastWeekEnd),
    ]);
    const thisRates = rejectionRateByVenture(thisWeekRows);
    const lastRates = rejectionRateByVenture(lastWeekRows);

    for (const [venture, thisRate] of Object.entries(thisRates)) {
      const lastRate = lastRates[venture];
      if (thisRate === null || lastRate === null) continue; // not enough volume either week -- skip, do not guess
      const spike = thisRate - lastRate;
      if (spike > DEMOTION_THRESHOLD) {
        // Fetch current autonomy_level
        const vrResp = await __httpRequest({ method: 'GET', url: SB_URL + '/rest/v1/venture_registry?slug=eq.' + encodeURIComponent(venture) + '&select=slug,autonomy_level,autonomy_history', headers: sbHeaders });
        const vr = Array.isArray(vrResp.body) ? vrResp.body[0] : null;
        if (!vr) continue;
        const levels = ['L1', 'L2', 'L3'];
        const idx = levels.indexOf(vr.autonomy_level || 'L1');
        const newLevel = levels[Math.max(0, idx - 1)]; // floor at L1, never auto-promote here
        if (newLevel === vr.autonomy_level) continue; // already at floor, nothing to demote

        const historyEntry = {
          at: new Date().toISOString(),
          from_level: vr.autonomy_level,
          to_level: newLevel,
          reason: 'rejection rate spiked ' + (spike * 100).toFixed(1) + 'pp week over week (' + (lastRate * 100).toFixed(1) + '% to ' + (thisRate * 100).toFixed(1) + '%)',
          source: 'vera_weekly_audit',
          metric_snapshot: { this_week_rate: thisRate, last_week_rate: lastRate, this_week_n: thisWeekRows.length, last_week_n: lastWeekRows.length },
        };
        const newHistory = (Array.isArray(vr.autonomy_history) ? vr.autonomy_history : []).concat([historyEntry]);

        await __httpRequest({
          method: 'PATCH',
          url: SB_URL + '/rest/v1/venture_registry?slug=eq.' + encodeURIComponent(venture),
          headers: sbWriteHeaders,
          body: { autonomy_level: newLevel, autonomy_history: newHistory },
        });

        await sbPost('audit_log', {
          event_type: 'vera_autonomy_demotion',
          actor: 'vera',
          target: venture,
          display_message: 'Vera demoted ' + venture + ' from ' + vr.autonomy_level + ' to ' + newLevel + ' (rejection rate spike ' + (spike * 100).toFixed(1) + 'pp)',
          details: JSON.stringify(historyEntry),
        });

        autonomyFindings.push({ band: 'autonomy', severity: 'high', subject: venture, reason: historyEntry.reason });
        cleanFlag = false;

        try {
          await __httpRequest({
            method: 'POST',
            url: 'https://api.telegram.org/bot' + TG_BOT + '/sendMessage',
            body: { chat_id: TG_CHAT, text: '⚠️ Vera: autonomy demotion\n' + venture + ': ' + vr.autonomy_level + ' -> ' + newLevel + '\n' + historyEntry.reason },
          });
        } catch (e) {}
      }
    }
  } catch (e) {
    // Never let this check take down the existing cadence/error audit or its Supabase/Telegram writes.
    autonomyFindings.push({ band: 'meta', severity: 'medium', subject: 'vera', reason: 'autonomy demotion check failed: ' + String(e.message || e).substring(0, 160) });
  }
}
findings.push(...autonomyFindings);

// ---------- write audit ----------
// vera_audit schema: audit_type (CHECK daily|weekly), agents_checked (text[]), clean (bool), findings (jsonb)
const auditInsert = await sbPost('vera_audit', {
  audit_type: auditType,
  agents_checked: auditedIds,
  clean: cleanFlag,
  findings: findings,
});
const auditWriteError = auditInsert && auditInsert.error ? auditInsert.error : null;

// ---------- write to audit_log (for CC Activity Feed) ----------
const summaryMsg = `Vera completed ${auditType} audit. ${findings.length} findings detected across ${auditedIds.length} workflows.`;
const activityInsert = await sbPost('audit_log', {
  event_type: 'vera_audit_complete',
  actor: 'vera',
  target: 'system',
  display_message: summaryMsg,
  details: JSON.stringify({ clean: cleanFlag, findings: findings.length })
});
const activityWriteError = activityInsert && activityInsert.error ? activityInsert.error : null;


// ---------- telegram summary ----------
const statusEmoji = cleanFlag ? '\ud83d\udfe2' : '\u26a0\ufe0f';
let tg = '\ud83d\udee1\ufe0f Vera: Audit complete (' + auditType + ') ' + statusEmoji + '\n';
tg += 'Workflows audited: ' + auditedIds.length + ' | Findings: ' + findings.length + '\n';
tg += 'Types: cron=' + (stats.cron||0) + ' webhook=' + (stats.webhook||0) + ' event=' + (stats.event||0) + ' manual=' + (stats.manual_only||0) + ' skipped=' + (stats.skipped||0);
if (auditWriteError) tg += '\n\u26a0\ufe0f vera_audit write failed: ' + auditWriteError;

if (findings.length > 0) {
  const highs = findings.filter(f => f.severity === 'high');
  const meds  = findings.filter(f => f.severity === 'medium');

  tg += '\n\nHigh severity: ' + highs.length + ' | Medium: ' + meds.length;

  if (highs.length > 0) {
    tg += '\n\n\ud83d\udd34 HIGH:';
    const shown = highs.slice(0, 8);
    for (const f of shown) {
      tg += '\n  \u2022 ' + f.subject + '\n      ' + f.reason;
    }
    if (highs.length > 8) tg += '\n  ... +' + (highs.length - 8) + ' more high';
  }

  if (meds.length > 0) {
    // Group mediums by owner prefix for compactness
    const medsByPrefix = {};
    for (const f of meds) {
      const k = prefixOf(f.subject);
      if (!medsByPrefix[k]) medsByPrefix[k] = [];
      medsByPrefix[k].push(f);
    }
    const prefixes = Object.keys(medsByPrefix).sort((a, b) => medsByPrefix[b].length - medsByPrefix[a].length);
    tg += '\n\n\ud83d\udfe1 MEDIUM (grouped):';
    let shown = 0;
    for (const p of prefixes) {
      if (shown >= 12) break;
      const count = medsByPrefix[p].length;
      tg += '\n  ' + p + ': ' + count + ' finding' + (count === 1 ? '' : 's');
      shown += count;
    }
    if (shown < meds.length) tg += '\n  ... +' + (meds.length - shown) + ' more medium';
  }
}

let tgOk = false;
try {
  await __httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + TG_BOT + '/sendMessage',
    body: { chat_id: TG_CHAT, text: tg },
  });
  tgOk = true;
} catch (e) {}

const durationMs = Date.now() - startedAt;

return [{ json: {
  audit_type: auditType,
  workflows_audited: auditedIds.length,
  clean: cleanFlag,
  findings_count: findings.length,
  findings: findings,
  stats: stats,
  audit_write_error: auditWriteError,
  telegram_sent: tgOk,
  duration_ms: durationMs,
  telegram_text: tg,
  activity_write_error: activityWriteError
} }];
